@startuml

class Location {
  + address : string
}

class Driver {
  + firstName : string
  + lastName : string
}

abstract class Vehicle {
  + vehicleNumber : string
}

class Truck {}

class Car {
  + numberOfSeats : int
}

class Van {}

class Order {
  + originLocation : string
  + destinationLocation : string
  + executionDate : date
}

Location "1" *-- "1..*" Driver
Location "1" *-- "1..*" Vehicle
Vehicle --|> Truck
Vehicle --|> Car
Vehicle --|> Van

Driver "1" -- "0..1" Order : carries
Driver "1" -- "0..1" Vehicle : drives

@enduml

